params.apply:
BandSettings s = u.band(0);
        s.depth = v;
        u.setBand(0, s);

BandSettings s = u.band(1);
        s.depth = v;
        u.setBand(1, s);

BandSettings s = u.band(2);
        s.depth = v;
        u.setBand(2, s);

BandSettings s = u.band(0);
        s.rangeDb = v;
        u.setBand(0, s);

BandSettings s = u.band(1);
        s.rangeDb = v;
        u.setBand(1, s);

BandSettings s = u.band(2);
        s.rangeDb = v;
        u.setBand(2, s);

const int i = static_cast<int>(v + 0.5);
        u.phase().setMode(i <= 0 ? dsp::PhaseMode::Host
                                 : (i == 1 ? dsp::PhaseMode::Free : dsp::PhaseMode::Trigger));
